 <div class="modal-body">
 <form method="POST" action="http://127.0.0.1:8000/consumers" id="consumerCreateForm">
 <input type="hidden" name="_token" value="4eUi5L34Pb9KtGRQwhX6TuoOUecfr4NaF2lQDPfE" autocomplete="off"> <div class="row g-3">
 <div class="col-md-6">
 <label class="form-label fw-semibold" for="full_name">Full Name</label>
 <input type="text" class="form-control" id="full_name" name="full_name" value="" placeholder="Enter consumer name" required>
 </div>
 <div class="col-md-6">
 <label class="form-label fw-semibold" for="account_number">Account Number</label>
 <input type="text" class="form-control" id="account_number" name="account_number" value="" placeholder="Leave blank to auto-generate 1, 2, 3...">
 </div>
 <div class="col-md-6">
 <label class="form-label fw-semibold" for="meter_number">Meter Number</label>
 <input type="text" class="form-control" id="meter_number" name="meter_number" value="" placeholder="MT-78455" required>
 </div>
 <div class="col-md-6">
 <label class="form-label fw-semibold" for="membership_type">Membership Type</label>
 <select class="form-select" id="membership_type" name="membership_type" required>
 <option value="Member" >Member</option>
 <option value="Non-Member" selected>Non-Member</option>
 </select>
 </div>
 <div class="col-md-8">
 <label class="form-label fw-semibold" for="service_address">Service Address</label>
 <input type="text" class="form-control" id="service_address" name="service_address" value="" placeholder="Enter service address">
 </div>
 <div class="col-md-4">
 <label class="form-label fw-semibold" for="contact_number">Contact Number</label>
 <input type="text" inputmode="numeric" pattern="[0-9]{10,15}" class="form-control js-digits-only" id="contact_number" name="contact_number" value="" placeholder="09XXXXXXXXX">
 </div>
 <div class="col-md-4">
 <label class="form-label fw-semibold" for="address_block">Block</label>
 <input type="text" class="form-control" id="address_block" name="address_block" value="" placeholder="e.g. Block 12">
 </div>
 <div class="col-md-4">
 <label class="form-label fw-semibold" for="address_street">Street</label>
 <input type="text" class="form-control" id="address_street" name="address_street" value="" placeholder="e.g. Maharlika Street">
 </div>
 <div class="col-md-4">
 <div class="form-check mt-4 pt-2">
 <input class="form-check-input" type="checkbox" value="1" id="housing_rights_documented" name="housing_rights_documented" >
 <label class="form-check-label" for="housing_rights_documented">Pag-IBIG / house rights documented</label>
 </div>
 </div>
 <div class="col-md-4">
 <div class="form-check mt-4 pt-2">
 <input class="form-check-input" type="checkbox" value="1" id="association_member" name="association_member" >
 <label class="form-check-label" for="association_member">Local association member</label>
 </div>
 </div>
 <div class="col-md-4">
 <div class="form-check mt-4 pt-2">
 <input class="form-check-input" type="checkbox" value="1" id="association_registered" name="association_registered" >
 <label class="form-check-label" for="association_registered">Officially registered</label>
 </div>
 </div>
 <div class="col-md-6">
 <label class="form-label fw-semibold" for="membership_renewal_date">Membership Date</label>
 <input type="date" class="form-control" id="membership_renewal_date" name="membership_renewal_date" value="">
 </div>
 </div>
 </form>
 </div>
 <div class="modal-footer">
 <button type="button" class="btn btn-light border" data-bs-dismiss="modal">Cancel</button>
 <button type="submit" form="consumerCreateForm" class="btn btn-primary">Save Consumer</button>
 </div>
 </div>
 </div>
 </div>
 
